}

exercises.solution:
public class Main {
    static Integer divide(int a, int b) {
        if (b == 0) return null;
        return a / b;
    }
    public static void main(String[] args) {
        if (divide(10, 2) == 5 && divide(10, 0) == null) System.out.print("ok");
    }
}

